# -*- coding: utf-8 -*-
# 第 13 批（A2）：補題──室內空氣品質管理法、噪音管制法施行細則
IA = "ENV-30"; NR = "ENV-39"
Q = [
# ---------- 室內空氣品質管理法（ENV-30） ----------
(IA,"第1條",1,"室內空品-立法目的",
 "室內空氣品質管理法之立法目的為何？",
 ["為改善室內空氣品質，以維護國民健康","為管制固定污染源，以維護空氣品質標準","為防制交通噪音，以維護生活環境安寧","為健全建築管理，以維護公共建築安全"],"a",
 "第1條：為改善室內空氣品質，以維護國民健康，特制定本法。第3條並定義室內指供公眾使用建築物之密閉或半密閉空間及大眾運輸工具之搭乘空間，室內空氣品質則指室內空氣污染物之濃度、空氣中之溼度及溫度。",
 "What is the legislative purpose of the Indoor Air Quality Management Act?",
 ["To improve indoor air quality so as to safeguard public health","To control stationary sources so as to meet ambient air standards","To control traffic noise so as to safeguard a quiet living environment","To improve building administration so as to safeguard public safety"],
 "Article 1; see also Article 3."),

(IA,"第2條",1,"室內空品-主管機關",
 "室內空氣品質管理法所稱主管機關為何？",
 ["中央為行政院環境保護署；直轄市為直轄市政府；縣（市）為縣（市）政府","中央為內政部營建署；直轄市為直轄市政府；縣（市）為縣（市）衛生局","中央為衛生福利部國民健康署；直轄市為直轄市政府；縣（市）為鄉鎮公所","中央為交通部路政司；直轄市為直轄市政府；縣（市）為縣（市）環保局"],"a",
 "第2條：本法所稱主管機關，在中央為行政院環境保護署；在直轄市為直轄市政府；在縣（市）為縣（市）政府。第4條並規定建築、經濟、衛生、交通等各級目的事業主管機關之權責劃分，且應輔導其主管場所改善室內空氣品質。",
 "Who are the competent authorities under the Indoor Air Quality Management Act?",
 ["The EPA of the Executive Yuan centrally; the municipal government; the county or city government","The Construction and Planning Agency centrally; the municipal government; the county health bureau","The Health Promotion Administration centrally; the municipal government; the township office","The Directorate of Highways centrally; the municipal government; the county environmental bureau"],
 "Article 2; see also Article 4."),

(IA,"第4條",2,"室內空品-中央權責",
 "中央主管機關就室內空氣品質管理應辦理之事項為何？",
 ["整合規劃及推動相關工作，訂定修正室內空氣品質管理法規、標準及檢驗測定或監測方法","核發建築物使用執照及室內裝修許可，並訂定裝修建材逸散污染物之國家標準","訂定大眾運輸工具空調設備通風量規範，並辦理醫療機構空調標準之查核作業","辦理傳染性病原之防護與管理及菸害防制，並核定各縣市噪音管制區之劃定"],"a",
 "第4條第一項：中央主管機關應整合規劃及推動室內空氣品質管理相關工作，訂定、修正室內空氣品質管理法規與室內空氣品質標準及檢驗測定或監測方法。同條第二項則將建築物通風設施與裝修建材管理劃歸建築主管機關、國家標準劃歸經濟主管機關、傳染性病原與菸害防制劃歸衛生主管機關、大眾運輸工具空調通風劃歸交通主管機關。",
 "What must the central competent authority do for indoor air quality management?",
 ["Integrate planning and promotion and set and amend the indoor air quality rules, standards and test methods","Issue building use licences and interior decoration permits and set national standards for building materials","Set ventilation requirements for mass transit air conditioning and audit hospital air conditioning standards","Manage infectious agents and tobacco hazards and approve the noise control zones of each county"],
 "Article 4, Paragraph 1; Paragraph 2 divides duties among other authorities."),

(IA,"第4條",3,"室內空品-目的事業權責",
 "依本法各級目的事業主管機關之權責劃分，下列何者正確？",
 ["建築主管機關掌建築物通風設施及裝修建材管理；交通主管機關掌大眾運輸工具空調通風量及維護管理","建築主管機關掌大眾運輸工具空調通風；交通主管機關掌建築物裝修建材及通風設施之管理相關事項","經濟主管機關掌傳染性病原防護與菸害防制；衛生主管機關掌空氣清淨機國家標準及裝修材料之標準","經濟主管機關掌醫療機構之空調標準訂定；衛生主管機關掌裝修材料逸散空氣污染物之國家標準事項"],"a",
 "第4條第二項：建築主管機關負責建築物通風設施、建築物裝修管理及裝修建材管理；經濟主管機關負責裝修材料與商品逸散空氣污染物之國家標準及空氣清淨機（器）國家標準；衛生主管機關負責傳染性病原之防護與管理、醫療機構之空調標準及菸害防制；交通主管機關負責大眾運輸工具之空調設備通風量及通風設施維護管理。同條第三項並規定各級目的事業主管機關應輔導其主管場所改善室內空氣品質。",
 "Which correctly states the division of duties among industry competent authorities?",
 ["Building authorities handle ventilation and decoration materials; transport authorities handle mass transit air conditioning","Building authorities handle mass transit air conditioning; transport authorities handle decoration materials and ventilation","Economic authorities handle infectious agents and tobacco control; health authorities handle air cleaner national standards","Economic authorities set hospital air conditioning standards; health authorities set standards for decoration materials"],
 "Article 4, Paragraph 2."),

(IA,"第5條",2,"室內空品-委託專業機構",
 "主管機關及各級目的事業主管機關得委託專業機構辦理之事項為何？",
 ["室內空氣品質之調查、檢驗、教育、宣導、輔導、訓練及研究有關事宜","室內空氣品質不合格場所之罰鍰裁處、停業命令及許可證廢止等處分","公告場所之現場檢查、命提供資料及對規避妨礙拒絕者之按次處罰","室內空氣品質標準之訂定修正及檢驗測定機構許可證之核發與換發"],"a",
 "第5條：主管機關及各級目的事業主管機關得委託專業機構，辦理有關室內空氣品質調查、檢驗、教育、宣導、輔導、訓練及研究有關事宜。裁罰、現場檢查與許可證核發等公權力事項則分別依第12條、第11條及罰則各條由主管機關行使，不在委託辦理之列。",
 "What may competent authorities commission professional institutions to handle?",
 ["Surveys, testing, education, publicity, guidance, training and research on indoor air quality","Imposing fines, ordering business suspension and revoking permits for non-compliant sites","On-site inspections, orders to provide data, and repeated penalties for obstruction","Setting and amending the indoor air quality standards and issuing testing organisation permits"],
 "Article 5."),

(IA,"第7條",2,"室內空品-符合標準",
 "公告場所之室內空氣品質應符合何標準？有無例外？該標準由何機關訂定？",
 ["應符合室內空氣品質標準；因不可歸責於所有人、管理人或使用人之事由致未符合者不在此限；由中央主管機關會商中央目的事業主管機關定之","應符合空氣品質標準；因天災或不可抗力致未符合者不在此限；由直轄市、縣（市）主管機關會商當地目的事業主管機關定之","應符合室內空氣品質標準；無任何例外情形；由中央目的事業主管機關會商各該公告場所所屬公會後共同訂定並公告","應符合建築技術規則所定通風標準；因場所使用變更致未符合者不在此限；由建築主管機關會商衛生主管機關定之"],"a",
 "第7條：公告場所之室內空氣品質應符合室內空氣品質標準，但因不可歸責於公告場所所有人、管理人或使用人之事由致未符合者，不在此限；該標準由中央主管機關會商中央目的事業主管機關依公告場所之類別及其使用特性定之。第15條並規定不符標準經命限期改善屆期未改善者，處五萬元以上二十五萬元以下罰鍰。",
 "What standard must announced sites meet, is there an exception, and who sets it?",
 ["The indoor air quality standards; excepted where not attributable to the owner, manager or user; set by the central authority with central industry authorities","The ambient air quality standards; excepted for natural disaster or force majeure; set by the municipal or county authority with local industry authorities","The indoor air quality standards; with no exception at all; set jointly by the central industry authority and the trade associations of the sites","The ventilation standards of the building technical rules; excepted where use has changed; set by building authorities with health authorities"],
 "Article 7; see also Article 15."),

(IA,"第9條",2,"室內空品-專責人員",
 "公告場所所有人、管理人或使用人就室內空氣品質維護管理專責人員之義務為何？",
 ["應置專責人員依維護管理計畫執行管理維護，該人員應符合中央主管機關規定資格並經訓練取得合格證書","應置專責人員但毋須具備任何資格，僅需於場所入口明顯處標示其姓名及聯絡方式即為已足","得委託檢驗測定機構代為執行管理維護，不需另置專責人員亦不需訂定維護管理計畫","應由直轄市、縣（市）主管機關指派專責人員進駐場所，其訓練費用由該場所負擔"],"a",
 "第9條：公告場所所有人、管理人或使用人應置室內空氣品質維護管理專責人員，依第8條之室內空氣品質維護管理計畫執行管理維護；專責人員應符合中央主管機關規定之資格，並經訓練取得合格證書；其設置、資格、訓練、合格證書之取得、撤銷、廢止等事項之辦法由中央主管機關定之。第17條規定違反第8條、第9條第一項或第二項經命限期改善屆期未改善者，處一萬元以上五萬元以下罰鍰。",
 "What duty do owners, managers or users have regarding dedicated indoor air quality personnel?",
 ["Appoint personnel to carry out the maintenance plan; they must meet central qualifications and hold a training certificate","Appoint personnel with no qualification required, merely posting their name and contact details at the entrance","Commission a testing organisation instead, with no dedicated person and no maintenance plan required","Have the municipal or county authority station personnel at the site, with training costs borne by the site"],
 "Article 9; penalties under Article 17."),

(IA,"第9條",2,"室內空品-計畫與人員",
 "公告場所之室內使用變更致影響其室內空氣品質時，維護管理計畫應如何處理？其執行由何人負責？",
 ["該計畫內容應立即檢討修正；由所置之室內空氣品質維護管理專責人員依計畫執行管理維護","該計畫應於次年度定期檢討時一併修正；由委託之檢驗測定機構負責依計畫執行管理維護","該計畫應報請主管機關核准後始得修正；由直轄市、縣（市）主管機關派員執行管理維護","該計畫毋須修正仍依原內容執行；由公告場所之建築物管理委員會負責執行管理與維護"],"a",
 "第8條：公告場所所有人、管理人或使用人應訂定室內空氣品質維護管理計畫據以執行，室內使用變更致影響室內空氣品質時，該計畫內容應立即檢討修正。第9條第一項：應置室內空氣品質維護管理專責人員，依該計畫執行管理維護。違反者依第17條經命限期改善屆期未改善處一萬元以上五萬元以下罰鍰，並再命限期改善。",
 "If a change of indoor use affects air quality, what happens to the maintenance plan and who executes it?",
 ["The plan must be reviewed and revised immediately; the appointed dedicated personnel execute it","The plan is revised at the next annual review; the commissioned testing organisation executes it","The plan may only be revised after authority approval; the municipal authority executes it on site","The plan need not be revised at all; the building management committee executes the original plan"],
 "Articles 8 and 9; penalties under Article 17."),

(IA,"第10條",2,"室內空品-檢驗測定",
 "公告場所所有人、管理人或使用人就室內空氣品質檢驗測定之義務為何？",
 ["應委託檢驗測定機構定期實施檢驗測定，並應定期公布檢驗測定結果及作成紀錄","得自行以市售偵測器材量測即可，毋須委託機構亦毋須公布結果或作成任何紀錄","應由主管機關委託之機構免費實施檢驗測定，場所僅須配合開放並保存結果紀錄","應每年委託建築師事務所辦理通風設施檢查，並將檢查結果函報目的事業主管機關"],"a",
 "第10條第一項：公告場所所有人、管理人或使用人應委託檢驗測定機構定期實施室內空氣品質檢驗測定，並應定期公布檢驗測定結果及作成紀錄。第11條第一項規定檢驗測定機構應取得中央主管機關核發許可證後始得辦理。第18條對違反第10條第一項、第二項或相關管理規定者，經命限期改善屆期未改善處五千元以上二萬五千元以下罰鍰。",
 "What testing duty falls on the owner, manager or user of an announced site?",
 ["Commission a licensed testing organisation to test periodically, and periodically publish results and keep records","Simply measure with off-the-shelf detectors, with no organisation, no publication and no records required","Have the authority commissioned body test free of charge, the site merely allowing access and keeping records","Have an architect firm inspect the ventilation yearly and report the results to the industry authority"],
 "Article 10, Paragraph 1; see also Articles 11 and 18."),

(IA,"第10條",3,"室內空品-自動監測",
 "經中央主管機關指定之公告場所，就室內空氣品質自動監測之義務為何？",
 ["應設置自動監測設施連續監測，最新結果應即時公布於該場所內或入口明顯處並作成紀錄","應設置自動監測設施連續監測，最新結果僅需按季函報主管機關備查而毋須對外公布","得選擇設置自動監測設施或增加人工檢驗測定頻率，二者擇一辦理即可並免作成紀錄","應設置自動監測設施連續監測，惟監測結果屬營業秘密不得公布亦不得提供主管機關"],"a",
 "第10條第二項：經中央主管機關指定之公告場所應設置自動監測設施，以連續監測室內空氣品質，其自動監測最新結果應即時公布於該場所內或入口明顯處，並應作成紀錄。同條第三項授權中央主管機關就檢驗測定項目、頻率、採樣數與採樣分布方式、監測項目、監測設施規範、結果公布方式、紀錄保存年限及保存方式等訂定辦法。第13條並對紀錄虛偽記載者處十萬元以上五十萬元以下罰鍰。",
 "For sites designated by the central authority, what continuous monitoring duty applies?",
 ["Install automatic monitoring and publish the latest results in real time inside or at the entrance, keeping records","Install automatic monitoring but only report the latest results quarterly to the authority without publication","Choose either automatic monitoring or more frequent manual testing, with no records required either way","Install automatic monitoring but treat results as trade secrets, publishing nothing and reporting nothing"],
 "Article 10, Paragraphs 2 and 3; see also Article 13."),

(IA,"第11條",2,"室內空品-檢測機構",
 "辦理本法規定檢驗測定之機構應具備何要件？各項污染物檢驗測定方法由何機關定之？",
 ["應取得中央主管機關核發許可證後始得辦理；檢驗測定方法及品質管制事項由中央主管機關公告","應向直轄市、縣（市）主管機關登記後即得辦理；檢驗測定方法由該機構自行訂定並報備","應取得目的事業主管機關同意函後始得辦理；檢驗測定方法由公告場所與機構雙方議定","應取得經濟部認證機構之認證後即得辦理；檢驗測定方法依國際標準組織規範逕行採用"],"a",
 "第11條：檢驗測定機構應取得中央主管機關核發許可證後，始得辦理本法規定之檢驗測定；其應具備之條件、設施、人員資格、許可證申請審查與有效期限、核換發、撤銷、廢止、停業、復業、查核、評鑑程序等辦法由中央主管機關定之；本法各項室內空氣污染物檢驗測定方法及品質管制事項，由中央主管機關公告之。第16條並對違反者處五萬元以上二十五萬元以下罰鍰，出具不實文書者得廢止其許可證。",
 "What must a testing organisation obtain, and who prescribes the testing methods?",
 ["A permit issued by the central authority; testing methods and QC matters are announced by the central authority","Only registration with the municipal or county authority; the organisation writes and files its own methods","A letter of consent from the industry authority; methods are agreed between the site and the organisation","Accreditation from a Ministry of Economic Affairs body; ISO standards are adopted directly as methods"],
 "Article 11; penalties under Article 16."),

(IA,"第12條",2,"室內空品-檢查權",
 "主管機關執行公告場所現場檢查、檢驗測定或查核紀錄時，應如何為之？場所方之義務為何？",
 ["應派員出示執行職務證明文件或顯示足資辨別標誌，並得命提供資料；場所不得規避、妨礙或拒絕","應於七日前以書面通知場所並取得同意後始得進入；場所得以營業秘密為由拒絕提供相關資料","應會同目的事業主管機關及當地警察機關始得執行；場所得要求先行提供檢查結果再決定配合","應委託檢驗測定機構代為執行現場檢查；場所僅須對該機構配合而對主管機關不負配合義務"],"a",
 "第12條：主管機關得派員出示有關執行職務之證明文件或顯示足資辨別之標誌，執行公告場所之現場檢查、室內空氣品質檢驗測定或查核檢（監）測紀錄，並得命提供有關資料，公告場所所有人、管理人或使用人不得規避、妨礙或拒絕。第14條並規定規避、妨礙或拒絕者，處十萬元以上五十萬元以下罰鍰，並得按次處罰。",
 "How does the authority conduct site inspections, and what is the site duty?",
 ["Staff show credentials or an identifying mark and may order data to be provided; the site may not evade, obstruct or refuse","Written notice seven days ahead and consent are needed; the site may refuse data citing trade secrets","Joint action with the industry authority and local police is needed; the site may see results before cooperating","A testing organisation performs inspections; the site owes cooperation only to that organisation"],
 "Article 12; penalties under Article 14."),

(IA,"第13條",2,"室內空品-紀錄不實",
 "公告場所所有人、管理人或使用人依第十條規定應作成之紀錄有虛偽記載者，罰鍰額度為何？",
 ["處新臺幣十萬元以上五十萬元以下罰鍰","處新臺幣五萬元以上二十五萬元以下罰鍰","處新臺幣一萬元以上五萬元以下罰鍰","處新臺幣五千元以上二萬五千元以下罰鍰"],"a",
 "第13條：公告場所所有人、管理人或使用人依本法第十條規定應作成之紀錄有虛偽記載者，處新臺幣十萬元以上五十萬元以下罰鍰。第14條對規避、妨礙或拒絕檢查者亦處十萬元以上五十萬元以下罰鍰並得按次處罰；第18條對違反第10條檢測申報管理規定者則處五千元以上二萬五千元以下罰鍰。",
 "What fine applies to false entries in the records required by Article 10?",
 ["A fine of NT$100,000 up to NT$500,000","A fine of NT$50,000 up to NT$250,000","A fine of NT$10,000 up to NT$50,000","A fine of NT$5,000 up to NT$25,000"],
 "Article 13."),

(IA,"第14條",2,"室內空品-規避檢查罰則",
 "規避、妨礙或拒絕主管機關依第十二條規定所為之檢查、檢驗測定或查核者，如何處罰？",
 ["處所有人、管理人或使用人十萬元以上五十萬元以下罰鍰，並得按次處罰","處所有人、管理人或使用人一萬元以上五萬元以下罰鍰，並命限期改善","處所有人、管理人或使用人五千元以上二萬五千元以下罰鍰，不得按次罰","處所有人、管理人或使用人五萬元以上二十五萬元以下罰鍰，並命停業"],"a",
 "第14條：規避、妨礙或拒絕依第12條規定之檢查、檢驗測定、查核或命提供有關資料者，處公告場所所有人、管理人或使用人新臺幣十萬元以上五十萬元以下罰鍰，並得按次處罰。與第13條紀錄虛偽記載之罰鍰額度相同，惟第13條未定按次處罰。第19條並規定罰鍰額度應依違反室內空氣品質標準程度及特性裁處。",
 "How is evasion or refusal of an Article 12 inspection punished?",
 ["A fine of NT$100,000 to NT$500,000 on the owner, manager or user, with repeated penalties allowed","A fine of NT$10,000 to NT$50,000 on the owner, manager or user, with an order to improve in time","A fine of NT$5,000 to NT$25,000 on the owner, manager or user, without repeated penalties allowed","A fine of NT$50,000 to NT$250,000 on the owner, manager or user, with an order to suspend business"],
 "Article 14; compare Article 13."),

(IA,"第16條",3,"室內空品-機構罰則",
 "檢驗測定機構違反第十一條第一項或相關管理規定者，如何處罰？出具不實文書者效果為何？",
 ["處五萬元以上二十五萬元以下罰鍰並命限期改善，屆期未改善按次處罰；出具不實文書者得廢止許可證","處十萬元以上五十萬元以下罰鍰並命立即停業，屆期未改善加倍處罰；出具不實文書者僅得書面告誡","處一萬元以上五萬元以下罰鍰並命限期改善，屆期未改善移送法辦；出具不實文書者應移請檢察官偵辦","處五千元以上二萬五千元以下罰鍰並命限期改善，屆期未改善不再處罰；出具不實文書者得暫停其業務"],"a",
 "第16條：檢驗測定機構違反第11條第一項或依第二項所定辦法中有關檢驗測定人員資格、查核、評鑑或檢驗測定業務執行之管理規定者，處新臺幣五萬元以上二十五萬元以下罰鍰，並命其限期改善，屆期未改善者按次處罰；檢驗測定機構出具不實之文書者，主管機關得廢止其許可證。第11條第一項規定機構應先取得中央主管機關核發之許可證。",
 "How are testing organisations punished for breaching Article 11 or its management rules?",
 ["NT$50,000 to NT$250,000 with an order to improve and repeated penalties; false documents may cost the permit","NT$100,000 to NT$500,000 with immediate suspension and doubled penalties; false documents draw a written warning","NT$10,000 to NT$50,000 with an order to improve and referral for prosecution; false documents go to prosecutors","NT$5,000 to NT$25,000 with an order to improve and no further penalty; false documents may suspend business"],
 "Article 16; see also Article 11."),

(IA,"第17條",2,"室內空品-計畫人員罰則",
 "公告場所所有人、管理人或使用人違反訂定維護管理計畫或設置專責人員規定者，如何處罰？",
 ["經命限期改善屆期未改善者，處一萬元以上五萬元以下罰鍰，並再命限期改善，屆期仍未改善按次處罰","不經限期改善即處十萬元以上五十萬元以下罰鍰，並得按次處罰至完成改善為止且不得申請延長","經命限期改善屆期未改善者，處五萬元以上二十五萬元以下罰鍰，並得逕行限制或禁止使用該場所","經命限期改善屆期未改善者，處五千元以上二萬五千元以下罰鍰，並廢止該場所之公告場所資格"],"a",
 "第17條：公告場所所有人、管理人或使用人違反第8條、第9條第一項或第二項規定者，經命其限期改善，屆期未改善者，處新臺幣一萬元以上五萬元以下罰鍰，並再命其限期改善；屆期仍未改善者，按次處罰。第8條為訂定並執行室內空氣品質維護管理計畫之義務，第9條為設置合格專責人員之義務。",
 "How is failure to keep a maintenance plan or appoint dedicated personnel punished?",
 ["After an unmet improvement order, NT$10,000 to NT$50,000, a further order, and repeated penalties if still unmet","Immediately NT$100,000 to NT$500,000 with repeated penalties until improved and no extension allowed at all","After an unmet improvement order, NT$50,000 to NT$250,000, and use of the site may be restricted outright","After an unmet improvement order, NT$5,000 to NT$25,000, and the announced site status is revoked"],
 "Article 17; duties under Articles 8 and 9."),

(IA,"第18條",2,"室內空品-檢測罰則",
 "公告場所違反檢驗測定、自動監測或紀錄保存等管理規定者，如何處罰？",
 ["經命限期改善屆期未改善者，處五千元以上二萬五千元以下罰鍰，並再命限期改善，屆期仍未改善按次處罰","經命限期改善屆期未改善者，處十萬元以上五十萬元以下罰鍰，並再命限期改善，屆期仍未改善加倍處罰","不經限期改善即處一萬元以上五萬元以下罰鍰，並得限制或禁止其使用該公告場所至改善完成為止","經命限期改善屆期未改善者，處五萬元以上二十五萬元以下罰鍰，並命其停止營業至查驗合格為止"],"a",
 "第18條：公告場所所有人、管理人或使用人違反第10條第一項、第二項或依第三項所定辦法中有關檢驗測定項目、頻率、採樣數與採樣分布方式、監測項目、頻率、監測設施規範、結果公布方式、紀錄保存年限、保存方式之管理規定者，經命限期改善屆期未改善，處新臺幣五千元以上二萬五千元以下罰鍰，並再命限期改善；屆期仍未改善者按次處罰。第13條對紀錄虛偽記載者則處十萬元以上五十萬元以下罰鍰。",
 "How are breaches of testing, monitoring or record-keeping management rules punished?",
 ["After an unmet improvement order, NT$5,000 to NT$25,000, a further order, and repeated penalties if still unmet","After an unmet improvement order, NT$100,000 to NT$500,000, a further order, and doubled penalties if unmet","Immediately NT$10,000 to NT$50,000, and use of the announced site may be restricted until improvement","After an unmet improvement order, NT$50,000 to NT$250,000, and business must stop until inspection passes"],
 "Article 18; compare Article 13."),

(IA,"第19條",2,"室內空品-裁罰準則",
 "依本法處罰鍰者，其額度應依何標準裁處？裁罰準則由何機關訂定？",
 ["應依違反室內空氣品質標準程度及特性裁處；裁罰準則由中央主管機關定之","應依公告場所之營業額及樓地板面積裁處；裁罰準則由直轄市政府定之","應依場所公眾聚集量及進出量裁處；裁罰準則由中央目的事業主管機關定之","應依違規次數及改善期間長短裁處；裁罰準則由各該場所所屬公會定之"],"a",
 "第19條：依本法處罰鍰者，其額度應依違反室內空氣品質標準程度及特性裁處；該裁罰準則由中央主管機關定之。相關子法即違反室內空氣品質管理法罰鍰額度裁罰準則。第20條並規定依本法命限期改善者，改善期間以九十日為限。",
 "By what criterion are fines set under this Act, and who prescribes the guidelines?",
 ["By the degree and nature of the breach of the indoor air quality standards; guidelines set centrally","By the turnover and floor area of the announced site; guidelines set by the municipal government","By the crowd size and footfall of the site; guidelines set by the central industry authority","By the number of violations and length of improvement; guidelines set by the trade association"],
 "Article 19; see also Article 20."),

(IA,"第20條",3,"室內空品-改善期限",
 "依本法命限期改善者，改善期間以多久為限？因天災或不可抗力未能完成改善時應如何處理？",
 ["改善期間以九十日為限；應於事由消滅後十五日內以書面敘明事由並檢具資料申請延長改善期限","改善期間以三十日為限；應於事由發生後七日內以書面敘明事由並檢具資料申請延長改善期限","改善期間以一百八十日為限；應於事由消滅後三十日內以口頭報告事由並事後補送相關文件","改善期間以六個月為限；應於事由消滅後六十日內以書面敘明事由並檢具資料申請延長期限"],"a",
 "第20條第一項：依本法命其限期改善者，改善期間以九十日為限；因天災或其他不可抗力事由致未能於改善期限內完成改善者，應於其事由消滅後十五日內，以書面敘明事由檢具相關資料向主管機關申請延長改善期限，主管機關應依實際狀況核定改善期限。第22條並規定未於限期改善期限屆至前檢具資料報請查驗者，視為未改善。",
 "How long is the improvement period, and what if force majeure prevents completion?",
 ["Ninety days at most; apply in writing with reasons and documents within fifteen days after the cause ends","Thirty days at most; apply in writing with reasons and documents within seven days after the cause arises","One hundred and eighty days at most; report orally within thirty days after the cause ends and file later","Six months at most; apply in writing with reasons and documents within sixty days after the cause ends"],
 "Article 20, Paragraph 1; see also Article 22."),

(IA,"第20條",3,"室內空品-展延上限",
 "公告場所未能於主管機關所定限期內改善者，得於何時提出具體改善計畫申請延長？延長期限上限為何？未切實執行者效果為何？",
 ["得於接獲限期改善之日起三十日內提出；延長最長不得超過六個月；未切實執行經查證屬實得立即終止改善期限","得於改善期限屆滿之日起三十日內提出；延長最長不得超過九十日；未切實執行者僅得縮短其改善期限","得於接獲限期改善之日起十五日內提出；延長最長不得超過一年；未切實執行者應加倍處以罰鍰處分","得於接獲限期改善之日起六十日內提出；延長最長不得超過三個月；未切實執行者得再申請一次延長"],"a",
 "第20條第二項：公告場所所有人、管理人或使用人未能於主管機關所定限期內改善者，得於接獲限期改善之日起三十日內提出具體改善計畫向主管機關申請延長改善期限，主管機關應依實際狀況核定，最長不得超過六個月；未切實依其所提之具體改善計畫執行，經查證屬實者，主管機關得立即終止其改善期限，並視為屆期未改善。",
 "When may a concrete improvement plan be filed for extension, what is the cap, and what if it is not followed?",
 ["Within thirty days of receiving the order; at most six months; the authority may end the period immediately","Within thirty days after the period expires; at most ninety days; the authority may only shorten the period","Within fifteen days of receiving the order; at most one year; the fine is doubled instead of any other step","Within sixty days of receiving the order; at most three months; one further extension may be applied for"],
 "Article 20, Paragraph 2."),

(IA,"第21條",3,"室內空品-情節重大",
 "第十五條第一項所稱情節重大，指下列何種情形？",
 ["不符標準之日起一年內經二次處罰仍繼續違反，或空氣品質嚴重惡化未立即採取緊急應變致有嚴重危害公眾健康之虞","不符標準之日起二年內經三次處罰仍繼續違反，或空氣品質不合格未於入口明顯處標示致民眾無從知悉其狀況","不符標準之日起六個月內經一次處罰仍繼續違反，或未依規定委託檢驗測定機構定期實施室內空氣品質檢驗測定","不符標準之日起一年內經五次處罰仍繼續違反，或未置符合資格之室內空氣品質維護管理專責人員執行管理維護"],"a",
 "第21條：第15條第一項所稱情節重大，指公告場所不符合第7條第一項所定室內空氣品質標準之日起一年內經二次處罰仍繼續違反本法規定，或公告場所室內空氣品質嚴重惡化而所有人、管理人或使用人未立即採取緊急應變措施致有嚴重危害公眾健康之虞者。情節重大者依第15條第一項得限制或禁止使用公告場所，必要時並得命其停止營業。",
 "What counts as a serious violation under Article 15, Paragraph 1?",
 ["Two penalties within a year of non-compliance and continued breach, or severe deterioration with no emergency response","Three penalties within two years and continued breach, or failure to post a non-compliance notice at the entrance","One penalty within six months and continued breach, or failure to commission periodic indoor air quality testing","Five penalties within a year and continued breach, or failure to appoint qualified dedicated maintenance personnel"],
 "Article 21; consequences under Article 15."),

(IA,"第22條",2,"室內空品-視為未改善",
 "公告場所於限期改善期限屆至前未檢具資料報請查驗者，其法律效果為何？",
 ["視為未改善","視為已完成改善","視為情節重大","視為自動放棄申辯"],"a",
 "第22條：未於限期改善之期限屆至前，檢具資料、符合室內空氣品質標準或其他符合本法規定之證明文件，向主管機關報請查驗者，視為未改善。第15條、第17條、第18條均以屆期未改善作為處罰要件，並定有按次處罰之規定。第20條第二項亦規定未切實依具體改善計畫執行者，視為屆期未改善。",
 "If no verification documents are filed before the improvement deadline, the effect is:",
 ["Deemed not improved","Deemed already improved","Deemed a serious case","Deemed to waive defence"],
 "Article 22; see also Articles 15, 17, 18 and 20."),

(IA,"第23條",1,"室內空品-施行細則",
 "室內空氣品質管理法之施行細則由何機關訂定？",
 ["由中央主管機關定之","由直轄市、縣（市）主管機關定之","由中央目的事業主管機關定之","由行政院會同立法院定之"],"a",
 "第23條：本法施行細則，由中央主管機關定之。第2條規定中央主管機關為行政院環境保護署。第7條第二項之室內空氣品質標準、第9條第三項之專責人員設置管理辦法、第10條第三項之檢驗測定管理辦法及第19條第二項之裁罰準則，亦均由中央主管機關訂定。",
 "Who prescribes the Enforcement Rules of this Act?",
 ["The central competent authority","The municipal or county authority","The central industry authority","The Executive Yuan with the Legislature"],
 "Article 23; see also Article 2."),

(IA,"第24條",1,"室內空品-施行日",
 "室內空氣品質管理法之施行日期規定為何？",
 ["本法自公布後一年施行","本法自公布日施行","本法自公布後六個月施行","本法自公布後二年施行"],"a",
 "第24條：本法自公布後一年施行。本法修正日期為民國一百年十一月二十三日，故自一百零一年十一月二十三日施行；室內空氣品質標準第5條亦明定自一百零一年十一月二十三日起施行，二者一致。",
 "When does the Indoor Air Quality Management Act take effect?",
 ["One year after promulgation","On the date of promulgation","Six months after promulgation","Two years after promulgation"],
 "Article 24."),

# ---------- 噪音管制法施行細則（ENV-39） ----------
(NR,"第1條",1,"噪音細則-法源",
 "噪音管制法施行細則係依何規定訂定？",
 ["依噪音管制法第三十六條規定訂定","依噪音管制法第十五條第三項規定訂定","依噪音管制法第十一條第一項規定訂定","依噪音管制法第九條第二項規定訂定"],"a",
 "第1條：本細則依噪音管制法（以下簡稱本法）第三十六條規定訂定之。噪音管制法第十五條第三項為環境音量標準之授權依據，第十一條第一項為機動車輛、民用航空器噪音管制標準之授權依據，第九條第二項則為噪音管制標準之授權依據，授權對象均不相同。",
 "The Enforcement Rules of the Noise Control Act are enacted under:",
 ["Article 36 of the Noise Control Act","Article 15, Paragraph 3 of the Noise Control Act","Article 11, Paragraph 1 of the Noise Control Act","Article 9, Paragraph 2 of the Noise Control Act"],
 "Article 1."),

(NR,"第2條",2,"噪音細則-管制標準",
 "本法第三條之管制標準以何者為準？音量單位為何？本法所稱機動車輛之定義為何？",
 ["以最高之容許音量為準，單位為分貝（dB）；指在道路上不依軌道或電力架設而以原動機行駛之車輛","以平均之容許音量為準，單位為赫茲（Hz）；指在道路上依軌道或電力架設而以原動機行駛之車輛","以最低之容許音量為準，單位為分貝（dB）；指在道路上以人力或獸力拖曳行駛之各類運輸工具","以均能音量之半數為準，單位為巴斯噶（Pa）；指在軌道上以電力驅動並供公眾運輸使用之車輛"],"a",
 "第2條：本法第三條之管制標準，以最高之容許音量為準，音量之單位為分貝（dB）；本法所稱機動車輛，指在道路上不依軌道或電力架設，而以原動機行駛之車輛。環境音量標準第2條第六款亦規定音量單位為分貝（dB（A）），A 指噪音計上 A 權位置之測定值。",
 "What basis and unit apply to the control standards, and how is a motor vehicle defined?",
 ["The maximum permissible level, in decibels (dB); a road vehicle driven by a prime mover, not on rails or wires","The average permissible level, in hertz (Hz); a road vehicle driven by a prime mover on rails or overhead wires","The minimum permissible level, in decibels (dB); a road conveyance drawn by human or animal power only","Half of the equivalent level, in pascals (Pa); an electrically driven rail vehicle used for public transport"],
 "Article 2."),

(NR,"第4條",1,"噪音細則-公告核定",
 "直轄市、縣（市）主管機關依本法第八條所為之公告，應如何辦理？",
 ["應報請中央主管機關核定","應報請中央主管機關備查","應報請目的事業主管機關同意","應報請當地議會審議通過"],"a",
 "第4條：直轄市、縣（市）主管機關依本法第八條所為之公告，應報請中央主管機關核定。第3條並規定直轄市、縣（市）主管機關應依噪音管制區劃定作業準則於所轄四類管制區內指定環境及交通噪音監測點，其數量及位置應報請中央主管機關備查，變更時亦同。",
 "How must a municipal or county announcement under Article 8 of the Act be handled?",
 ["It must be submitted to the central authority for approval","It must be submitted to the central authority for recordation","It must be submitted to the industry authority for consent","It must be submitted to the local council for resolution"],
 "Article 4; compare Article 3."),

(NR,"第5條",2,"噪音細則-裁處機關",
 "違反依本法第十一條第一項所定標準，或規避、妨礙、拒絕檢查或鑑定者，由何機關裁處？",
 ["由違規行為所在地之直轄市、縣（市）主管機關裁處","由違規人戶籍所在地之直轄市、縣（市）主管機關裁處","由中央主管機關統一裁處後交由地方機關執行","由陳情人所在地之鄉（鎮、市、區）公所裁處"],"a",
 "第5條：違反依本法第十一條第一項所定標準者，或違反本法第十九條第三項規定規避、妨礙或拒絕檢查或鑑定者，由違規行為所在地直轄市、縣（市）主管機關裁處。第13條並規定各級主管機關指派進入公私場所檢查或鑑定噪音狀況之人員，自一百年七月一日起應經中央主管機關或其委託機構訓練合格並領有證書。",
 "Who imposes penalties for exceeding standards or obstructing inspection or appraisal?",
 ["The municipal or county authority where the violation took place","The municipal or county authority of the violator household registration","The central authority, which imposes them and has localities enforce","The township or district office where the complainant resides"],
 "Article 5; see also Article 13."),

(NR,"第6條",2,"噪音細則-快速道路",
 "本法第十四條所稱快速道路，指下列何者？",
 ["高速公路及快速公路交通管制規則規定之快速公路，及市區道路及附屬工程設計標準規定之快速道路","公路法規定之省道及縣道，與市區道路及附屬工程設計標準規定之主要道路及次要道路等各級道路","都市計畫法所劃設之計畫道路，及區域計畫法所劃設之鄉道、產業道路與其他經指定之交通系統","大眾捷運法所定之專用路權路段，及鐵路法所定之鐵路路線與其兩側一定範圍內之附屬設施用地"],"a",
 "第6條第一項：本法第十四條所稱快速道路，指高速公路及快速公路交通管制規則規定之快速公路，及市區道路及附屬工程設計標準規定之快速道路。第二項則規定本法第十五條所稱其他交通所產生之噪音，範圍與快速道路不同。環境音量標準第2條第二款亦以本法第十四條第一項快速道路以外之道路界定其適用範圍。",
 "What does expressway mean under Article 14 of the Act?",
 ["Expressways under the freeway and expressway traffic rules, and expressways under the urban road design standards","Provincial and county highways under the Highway Act, plus primary and secondary roads under urban road standards","Planned roads designated under the Urban Planning Act and township and industrial roads under regional planning","Exclusive right-of-way sections under the Mass Rapid Transit Act and railway lines under the Railway Act"],
 "Article 6, Paragraph 1."),

(NR,"第6條",2,"噪音細則-其他交通噪音",
 "本法第十五條所稱其他交通所產生之噪音，包括下列何者？",
 ["快速道路以外之公路法省道與縣道、市區道路標準之主要道路與次要道路，及其他經中央主管機關指定之交通系統或道路","高速公路及快速公路交通管制規則規定之快速公路，及市區道路及附屬工程設計標準規定之各級快速道路與聯絡道路","僅限於工廠、營建工程、娛樂場所及擴音設施等非移動性噪音源所產生並經主管機關公告管制之各類噪音","僅限於民用航空器起降所產生之航空噪音，及軍用航空器起降航空站周圍地區所發生之各類飛航噪音"],"a",
 "第6條第二項：本法第十五條所稱其他交通所產生之噪音，指下列所產生之交通噪音：前項快速道路以外之公路法規定之省道、縣道；市區道路及附屬工程設計標準規定之主要道路、次要道路；其他經中央主管機關指定之交通系統或道路。第7條並規定本法第十四條第一項陸上運輸系統噪音改善計畫及第十五條第一項其他交通噪音改善計畫應包括之事項。",
 "What is included in other traffic noise under Article 15 of the Act?",
 ["Provincial and county highways other than expressways, primary and secondary urban roads, and other designated systems","Expressways under the freeway and expressway traffic rules and all grades of urban expressways and link roads","Only non-mobile sources such as factories, construction works, entertainment venues and amplification devices","Only aircraft noise from civil aviation take-offs and landings and military aircraft operations near airports"],
 "Article 6, Paragraph 2; see also Article 7."),

(NR,"第8條",3,"噪音細則-補助計畫期限",
 "交通噪音改善計畫經核定無法於營運或管理範圍內改善者，營運或管理機關（構）應於何期限內訂定補助計畫送核定？",
 ["應自核定之日起一百八十日內訂定噪音補助計畫，送交直轄市、縣（市）主管機關核定","應自核定之日起六十日內訂定噪音補助計畫，送交中央主管機關核定並公告實施內容","應自核定之日起九十日內訂定噪音補助計畫，送交目的事業主管機關備查後即得執行","應自核定之日起一年內訂定噪音補助計畫，送交當地鄉（鎮、市、區）公所核定實施"],"a",
 "第8條第一項：噪音改善計畫經直轄市、縣（市）主管機關核定無法於其營運或管理範圍內改善交通噪音者，營運或管理機關（構）應自核定之日起一百八十日內，依本法第十四條第一項或第十五條第一項訂定陸上運輸系統噪音補助計畫或其他交通噪音補助計畫，送交直轄市、縣（市）主管機關核定。第10條就航空噪音補助計畫亦定有相同之一百八十日期限。",
 "If traffic noise cannot be improved within the operator scope, when must a subsidy plan be filed?",
 ["Within one hundred and eighty days of approval, submitted to the municipal or county authority for approval","Within sixty days of approval, submitted to the central competent authority for approval and publication","Within ninety days of approval, submitted to the industry competent authority for recordation only","Within one year of approval, submitted to the local township or district office for its approval"],
 "Article 8, Paragraph 1; compare Article 10."),

(NR,"第8條",3,"噪音細則-補助對象",
 "交通噪音補助計畫所補助地區之建築物應符合何條件？補助次數限制為何？",
 ["應為九十九年一月二十一日發布之陸上運輸系統噪音管制標準及環境音量標準施行日前，或新建計畫核定前之既有合法建築物；以補助一次為限","應為任何領有使用執照之建築物，不問其興建先後及是否合法，均得申請補助；每五年得申請補助一次且不受總次數之限制","應為位於第一類及第二類噪音管制區內之住宅及學校建築物，且屋齡須達二十年以上者；以補助三次為限並得逐年申請","應為經直轄市、縣（市）主管機關指定公告之航空噪音防制區內建築物，不問合法與否；補助次數由主管機關逐案核定"],"a",
 "第8條第二項：補助計畫所補助地區之建築物應符合下列情形之一，並以補助一次為限：中華民國九十九年一月二十一日訂定發布之陸上運輸系統噪音管制標準及九十九年一月二十一日修正發布之環境音量標準施行日前之既有合法建築物；或前款情形以外且為陸上運輸系統及其他交通之新建計畫核定前之既有合法建築物。同條第三項並列明補助計畫應包括之事項。",
 "Which buildings qualify for a traffic noise subsidy plan, and how often may they be subsidised?",
 ["Lawful buildings predating the 21 January 2010 land transport and ambient noise standards, or predating a new transport project; subsidised once only","Any building with an occupancy permit, regardless of when built or whether lawful; one subsidy every five years with no overall cap on the number","Residential and school buildings in Class 1 and Class 2 control zones aged at least twenty years; subsidised up to three times with yearly applications","Buildings inside an announced aircraft noise control zone whether lawful or not; the number of subsidies decided case by case by the authority"],
 "Article 8, Paragraph 2."),

(NR,"第9條",3,"噪音細則-航空改善計畫",
 "民用機場、民用塔台所轄軍民合用機場航空噪音改善計畫，其所採取之噪音防制措施應包括下列何者？",
 ["減少噪音源及其音量、降低機場噪音、調整操作程序及管制試車時段、應有環保專職人員、協商擬訂航空站周圍土地使用對策","變更航空站之經營主體、提高起降架次以分散噪音、縮短跑道長度、增設航廈設施、辦理周邊土地徵收與住戶強制遷移作業","限制民航機夜間全面停飛、加倍收取降落費用作為補助財源、要求航空公司汰換機隊、由主管機關代為執行防音設施工程","僅辦理噪音監測與資料公布、受理民眾陳情、辦理環境影響評估、並將結果送交中央主管機關備查而無須採取實體措施"],"a",
 "第9條第二項：航空噪音改善計畫所採取之噪音防制措施，應包括減少噪音源及其音量、降低機場噪音、調整操作程序及管制試車時段、應有環保專職人員、協商有關機關擬訂航空站周圍土地之使用對策，及其他應採之防制措施。同條第一項並列明改善計畫應包括執行機關、噪音發生源狀況、改善前量測結果（含頻譜分析）、防制措施內容、功能評估、執行期程、可行性分析等事項。",
 "Which measures must a civil airport aircraft noise improvement plan include?",
 ["Reducing sources and levels, lowering airport noise, adjusting procedures and engine test hours, dedicated staff, land use policy","Changing the airport operator, raising movements to spread noise, shortening runways, expanding terminals, compulsory relocation","Banning all night flights, doubling landing fees for funding, forcing fleet replacement, and authority-built soundproofing works","Only monitoring and publishing data, handling complaints, running an impact assessment, with no physical measures at all"],
 "Article 9, Paragraphs 1 and 2."),

(NR,"第10條",2,"噪音細則-航空補助計畫",
 "航空噪音改善計畫經核定無法於營運或管理範圍內改善者，其補助計畫應包括下列何項內容？",
 ["補助學校、公共設施、住戶設置防音設施，並記載所補助噪音防制設施之位置、規模及功能等設計圖說","逕行徵收機場周圍土地並辦理住戶遷移，並記載徵收範圍、補償金額及安置方案等相關作業圖說","補助航空業者汰換低噪音機型，並記載航空器機型、架次及汰換期程等營運改善計畫相關資料","補助地方政府辦理噪音監測站設置，並記載監測站位置、儀器規格及資料傳輸方式等技術規範"],"a",
 "第10條：航空噪音改善計畫經核定無法於營運或管理範圍內改善者，營運或管理機關（構）應自核定之日起一百八十日內訂定航空噪音補助計畫送核定；補助計畫應包括補助學校、公共設施、住戶設置防音設施，所補助相關噪音防制設施內容說明並記載其位置、規模及功能等設計圖說，補助設施之改善功能評估，計畫執行期程及其他經主管機關指定之文件。核定程序依第7條第二項辦理。",
 "What must an aircraft noise subsidy plan include?",
 ["Subsidies for soundproofing at schools, public facilities and households, with drawings of location, scale and function","Direct expropriation of land around the airport and relocation of households, with maps, compensation and resettlement plans","Subsidies for airlines to replace aircraft with quieter types, with aircraft types, movements and replacement schedules","Subsidies for local governments to build monitoring stations, with station sites, instrument specifications and data links"],
 "Article 10; approval follows Article 7, Paragraph 2."),

(NR,"第11條",3,"噪音細則-軍用機場計畫",
 "軍用塔台所轄軍民合用機場及專供軍用航空器起降航空站之航空噪音改善計畫，其編製有何特別考量？防制措施應包括何者？",
 ["在不影響國防、飛航安全或國家機密之情形下編製；措施包括訂定環保航線、管制試車或訓練飛行時段、建置環保陳情專線","與民用機場改善計畫完全相同並無任何特別考量；措施僅限於補助住戶設置防音設施及調整民用航空器之起降時段","一律免予編製改善計畫並免受本法拘束；措施由國防主管機關自行決定且不需送直轄市、縣（市）主管機關核定","應公開全部飛航資料供民眾查閱以昭公信；措施包括全面禁止夜間訓練飛行及對周邊住戶發放噪音補償金"],"a",
 "第11條第一項：本法第十五條第二項軍用塔台所轄軍民合用機場航空噪音改善計畫及第十七條專供軍用航空器起降航空站之航空噪音改善計畫，在不影響國防、飛航安全或涉及國家機密或其他法律、法規命令規定應秘密或限制、禁止公開之情形下，應包括執行機關、噪音發生源狀況、改善前量測結果、防制措施、功能評估、執行期程等事項。第二項所定措施包括減少噪音源及其音量、降低機場噪音、補助學校圖書館醫療機構公共設施住戶設置防音設施、訂定環保航線、管制試車或訓練飛行時段、建置環保陳情專線及應有環保專職人員等。",
 "What special consideration applies to military airfield noise improvement plans, and what measures are included?",
 ["Drafted without prejudice to defence, flight safety or state secrets; measures include eco-routes, engine test and training limits, complaint lines","Identical to civil airport plans with no special consideration; measures cover only household soundproofing subsidies and schedule changes","No plan is required at all and the Act does not apply; measures are decided by defence authorities without local approval","All flight data must be published for public inspection; measures include a total night training ban and cash compensation"],
 "Article 11, Paragraphs 1 and 2."),

(NR,"第13條",2,"噪音細則-檢查人員",
 "各級主管機關指派進入公、私場所檢查或鑑定噪音狀況之人員，應具備何資格？自何時起適用？",
 ["應經中央主管機關或其委託之機構訓練合格並領有證書；自中華民國一百年七月一日起適用","應經直轄市、縣（市）主管機關甄選並具備技師資格；自中華民國九十九年三月十一日起適用","應經噪音管制專責機構認證並取得乙級以上證照；自中華民國一百零一年一月一日起適用","應由環境檢驗測定機構指派並具三年以上經驗；自中華民國一百零三年七月一日起適用"],"a",
 "第13條：本法第十九條第一項所定各級主管機關指派進入公、私場所檢查或鑑定噪音狀況之人員，自中華民國一百年七月一日起，應經中央主管機關或其委託之機構訓練合格並領有證書。第5條並規定違反本法第十九條第三項規避、妨礙或拒絕檢查或鑑定者，由違規行為所在地直轄市、縣（市）主管機關裁處。",
 "What qualification must noise inspection or appraisal personnel hold, and from when?",
 ["Training passed with a certificate from the central authority or its commissioned body; from 1 July 2011","Selection by the municipal or county authority plus a professional engineer licence; from 11 March 2010","Certification by a noise control body with a Class B or higher licence; from 1 January 2012","Assignment by an environmental testing organisation with three years experience; from 1 July 2014"],
 "Article 13; see also Article 5."),

(NR,"第15條",2,"噪音細則-復工申請",
 "經主管機關命停工、停業或停止使用，或經命改善而自報停工者，恢復使用或復工前應如何辦理？",
 ["應檢具改善完成報告書及相關文件向該管直轄市、縣（市）主管機關申請復工，經查驗合格後始得恢復","應於改善完成後逕行復工並於三十日內函報直轄市、縣（市）主管機關備查，毋須事前申請或查驗","應向中央主管機關申請解除列管，經公告後始得恢復使用，直轄市、縣（市）主管機關不得查驗","應由目的事業主管機關會同警察機關現場勘查同意後即得復工，毋須檢具任何改善完成報告文件"],"a",
 "第15條：經直轄市、縣（市）主管機關命停工、停業或停止使用或經命改善而自報停工、停業或停止使用者，應於恢復使用或復工前，檢具改善完成報告書及相關文件，向該管直轄市、縣（市）主管機關申請復工；主管機關對於該申請經查驗合格後，始得准予恢復使用或復工。第16條並列明改善完成報告書應記載之事項。",
 "Before resuming after an ordered or self-reported shutdown, what must be done?",
 ["File a completion report and documents with the municipal or county authority and pass its inspection first","Resume at once after improvement and file with the municipal or county authority within thirty days","Apply to the central authority for de-listing and resume after publication, with no local inspection","Resume once the industry authority and police inspect the site, with no completion report required"],
 "Article 15; see also Article 16."),

(NR,"第16條",2,"噪音細則-報告書內容",
 "噪音改善完成報告書應記載之事項，下列何者正確？",
 ["噪音發生源狀況及構造位置、改善前量測結果及成因分析、防制措施內容與設計圖說、改善功效、完成安裝設施相片","營運機關之組織編制與人事名冊、年度預算執行情形、員工教育訓練紀錄、陳情案件統計、內部稽核作業報告","噪音管制區劃定範圍與公告文件、監測點位置座標、全年監測資料統計、鄰近土地使用分區圖、都市計畫書圖","環境影響評估書件與審查結論、水污染防制措施計畫、空氣污染防制設施清冊、廢棄物清理計畫及緊急應變手冊"],"a",
 "第16條：改善完成報告書應記載噪音發生源狀況說明及其構造、位置（含陳情戶位置或量測點），改善前噪音量測結果及其成因分析、影響程度，所採取相關噪音防制措施內容說明並記載噪音防制設施之位置、規模及功能等設計圖說，採取噪音防制措施之改善功效，完成安裝之噪音防制設施相片資料，及其他經主管機關指定之文件。第15條規定應檢具該報告書申請復工並經查驗合格。",
 "What must a noise improvement completion report record?",
 ["Source condition and location, pre-improvement measurements and causes, measures and drawings, effectiveness, photos of installations","The operator organisation chart and staff roster, budget execution, staff training records, complaint statistics, internal audit report","The noise control zone boundaries and notices, monitoring point coordinates, annual data, land use zoning maps and plans","The environmental impact statement and conclusions, water pollution plan, air control facility list, waste plan and emergency manual"],
 "Article 16; filed under Article 15."),

(NR,"第17條",1,"噪音細則-施行",
 "噪音管制法施行細則之施行日期規定為何？",
 ["本細則自發布日施行","本細則自發布後一年施行","本細則自公布後六個月施行","本細則自中央主管機關指定日施行"],"a",
 "第17條：本細則自發布日施行。環境音量標準第6條亦規定自發布日施行；相對而言，室內空氣品質管理法第24條規定自公布後一年施行，室內空氣品質標準第5條則明定特定施行日期。",
 "When do these Enforcement Rules take effect?",
 ["From the date of promulgation","One year after promulgation","Six months after promulgation","On a date designated centrally"],
 "Article 17."),
]
